CREATE TABLE IF NOT EXISTS m4d_representative_passport (
    id bigserial PRIMARY KEY,
    date_issue timestamp NOT NULL,
    department_code varchar(255) NOT NULL,
    representative_id int8 NOT NULL,
    series_number varchar(255) NOT NULL,
    who_issue varchar(255) NOT NULL,
    FOREIGN KEY (representative_id) REFERENCES m4d_representative (id)
    ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE INDEX idx_passport_representative_id ON m4d_representative_passport (representative_id);
CREATE INDEX idx_passport_series_number ON m4d_representative_passport (series_number);
